{
  "spec": {
    "containers": [
      {
        "name": "writer",
        "image": "busybox:latest",
        "command": ["sh", "-c", "echo \'<h1 >Hello from Kubernetes!</h1>\' > /srv/index.html"],
        "volumeMounts": [
